package com.sanctuarygames.createtransit.elevator.client;
import com.sanctuarygames.createtransit.CreateTransit;import com.sanctuarygames.createtransit.elevator.*;import com.sanctuarygames.createtransit.elevator.model.*;
import net.minecraft.client.*;import net.minecraft.client.renderer.*;import net.minecraft.core.*;import net.minecraft.world.phys.*;import com.mojang.math.Axis;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RenderLevelStageEvent;
@EventBusSubscriber(modid=CreateTransit.MOD_ID,value=Dist.CLIENT)
public final class CabinPlacementPreview {
 @SubscribeEvent public static void render(RenderLevelStageEvent event){if(event.getStage()!=RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS)return;var mc=Minecraft.getInstance();if(mc.level==null||mc.player==null||!(mc.player.getMainHandItem().getItem() instanceof ModelCabinItem))return;
  ElevatorDriveEntity d=null;var plan=ModelCabinItem.plan(mc.player.getMainHandItem());
  if(plan.contains("Position")&&mc.level.dimension().location().toString().equals(plan.getString("Dimension"))){var p=BlockPos.of(plan.getLong("Position"));if(mc.player.distanceToSqr(Vec3.atCenterOf(p))>256)return;d=new ElevatorDriveEntity(p,ElevatorRegistry.DRIVE.get().defaultBlockState().setValue(ElevatorPartBlock.FACING,Direction.from2DDataValue(plan.getInt("Facing"))));d.setLevel(mc.level);}
  else if(mc.hitResult instanceof BlockHitResult hit&&mc.level.getBlockEntity(hit.getBlockPos()) instanceof ElevatorDriveEntity existing){d=existing;if(d.model()!=null&&d.model().active())return;}
  if(d==null&&mc.hitResult instanceof BlockHitResult hit&&mc.level.getBlockState(hit.getBlockPos()).getBlock() instanceof ElevatorGuideRailBlock){d=ElevatorGuideRailBlock.drive(mc.level,hit.getBlockPos());if(d!=null&&d.model()!=null&&d.model().active())return;}
  if(d==null)return;var c=d.model()==null?CabinConfiguration.defaults(3,CabinConfiguration.Variant.SOLID):d.model().config();var e=new ModelCabinEntity(ElevatorRegistry.MODEL_CABIN.get(),mc.level);e.configure(c);e.bind(d);var a=d.anchor();e.setPos(d.model()==null?new Vec3(a.getX(),a.getY()+.875,a.getZ()):d.model().placementOrigin(a.getY()));e.updateBounds();var box=e.getBoundingBox();boolean clear=d.model()==null?mc.level.getEntitiesOfClass(ModelCabinEntity.class,box).isEmpty():d.model().placementClear(e);
  var camera=event.getCamera().getPosition();var pose=event.getPoseStack();var buffers=mc.renderBuffers().bufferSource();pose.pushPose();pose.translate(-camera.x,-camera.y,-camera.z);LevelRenderer.renderLineBox(pose,buffers.getBuffer(RenderType.lines()),box,clear?.2f:1,clear?1:.2f,.3f,.8f);
  var mount=plan.contains("Position")?ModelCabinItem.compactMount(d.getBlockPos(),d.getBlockState().getValue(ElevatorPartBlock.FACING)):d.getBlockPos();LevelRenderer.renderLineBox(pose,buffers.getBuffer(RenderType.lines()),new AABB(mount).expandTowards(0,1,0),.15f,.6f,1,1);
  var entrance=e.worldBox(new CabinGeometry.Box(CabinGeometry.left(c),.125,CabinGeometry.INSET,CabinGeometry.left(c)+CabinGeometry.width(c),2.125,CabinGeometry.INSET+.5));LevelRenderer.renderLineBox(pose,buffers.getBuffer(RenderType.lines()),entrance,1,.75f,.1f,1);
  pose.translate(e.getX(),e.getY(),e.getZ());pose.mulPose(Axis.YP.rotationDegrees(-e.facing().get2DDataValue()*90));pose.translate(e.offsetX(),0,e.offsetZ());pose.scale((float)e.widthScale(),1,(float)e.depthScale());ModelCabinRenderer.draw(c,CabinGeometry.body(c),pose,buffers,LightTexture.FULL_BRIGHT,.25f);ModelCabinRenderer.draw(c,CabinGeometry.doors(c,0,0),pose,buffers,LightTexture.FULL_BRIGHT,.25f);pose.popPose();
 }
}
